83	class LibrarySpec extends AnyFreeSpec with ChiselSim {
84	  "ForceZero when invalid" in {
85	    simulate(new ForceZeroTester) { dut =>
86	      dut.io.in.bits.poke(9001)
87	      dut.io.in.valid.poke(0)
88	      dut.clock.step()
89	      dut.io.out.bits.expect(0)
90	    }
91	  }
92	
93	  "ForceZeroForceZero propogates when valid" in {
94	    simulate(new ForceZeroTester) { dut =>
95	      dut.io.in.bits.poke(9001)
96	      dut.io.in.valid.poke(1)
97	      dut.clock.step()
98	      dut.io.out.bits.expect(9001)
99	    }
100	  }
101	
102	  "Zip32 Words" in {
103	    simulate(new Zip32Tester) { dut =>
104	      dut.io.sz.poke(4)
105	      dut.io.a.poke(5)
106	      dut.io.b.poke(3163)
107	      dut.io.out.expect((3163L << 32L) | 5)
108	    }
109	  }
110	
111	  "Zip32 Halves" in {
112	    simulate(new Zip32Tester) { dut =>
113	      dut.io.sz.poke(2)
114	      dut.io.a.poke((7L << 16L) | 3)
115	      dut.io.b.poke((11L << 16L) | 5)
116	      dut.io.out.expect((11L << 48L) | (7L << 32L) | (5L << 16L) | 3L)
117	    }
118	  }
119	
120	  "Zip32 Bytes" in {
121	    simulate(new Zip32Tester) { dut =>
122	      dut.io.sz.poke(1)
123	      dut.io.a.poke((37L << 16L) | (7L << 8L) | 3)
124	      dut.io.b.poke((43L << 16L) | (11L << 8L) | 5)
125	      dut.io.out.expect((43L << 40L) | (37L << 32L) | (11L << 24L) | (7L << 16L) | (5L << 8L) | 3L)
126	    }
127	  }
128	
129	  "RotateVectorLeft" in {
130	    simulate(new RotateVectorLeftTester) { dut =>
131	      val valids = Seq.fill(16)(Random.between(0, 2))
132	      val data = Seq.fill(16)(Random.between(0, 2147483647))
133	      for (i <- 0 until 16) {
134	        dut.io.in(i).valid.poke(valids(i))
135	        dut.io.in(i).bits.poke(data(i))
136	      }
137	
138	      // Check that for all possible shifts `t`, input[o] = output[o + t]
139	      for (t <- 0 until 16) {
140	        dut.io.shift.poke(t)
141	        for (o <- 0 until 16) {
142	          var targetIndex = o + t
143	          if (targetIndex >= 16) {
144	            targetIndex = targetIndex - 16
145	          }
146	          dut.io.out(targetIndex).valid.expect(valids(o))
147	          dut.io.out(targetIndex).bits.expect(data(o))
148	        }
149	      }
150	    }
151	  }
152	
153	  "RotateVectorRight" in {
154	    simulate(new RotateVectorRightTester) { dut =>
155	      val valids = Seq.fill(16)(Random.between(0, 2))
156	      val data = Seq.fill(16)(Random.between(0, 2147483647))
157	      for (i <- 0 until 16) {
158	        dut.io.in(i).valid.poke(valids(i))
159	        dut.io.in(i).bits.poke(data(i))
160	      }
161	
162	      // Check that for all possible shifts `t`, input[o] = output[o - t]
163	      for (t <- 0 until 16) {
164	        dut.io.shift.poke(t)
165	        for (o <- 0 until 16) {
166	          var targetIndex = o - t
167	          if (targetIndex < 0) {
168	            targetIndex = targetIndex + 16
169	          }
170	          dut.io.out(targetIndex).valid.expect(valids(o))
171	          dut.io.out(targetIndex).bits.expect(data(o))
172	        }
173	      }
174	    }
175	  }
176	
177	  "ShiftVectorLeft" in {
178	    simulate(new ShiftVectorLeftTester) { dut =>
179	      val valids = Seq.fill(16)(Random.between(0, 2))
180	      val data = Seq.fill(16)(Random.between(0, 2147483647))
181	      for (i <- 0 until 16) {
182	        dut.io.in(i).valid.poke(valids(i))
183	        dut.io.in(i).bits.poke(data(i))
184	      }
185	
186	      for (t <- 0 until 16) {
187	        dut.io.shift.poke(t)
188	        for (o <- 0 until 16) {
189	          var targetIndex = o + t
190	          if (targetIndex >= 16) {
191	            targetIndex = targetIndex - 16
192	          }
193	          if (targetIndex < o) {
194	            dut.io.out(targetIndex).valid.expect(0.U.asTypeOf(dut.io.out(0).valid))
195	            dut.io.out(targetIndex).bits.expect(0.U.asTypeOf(dut.io.out(0).bits))
196	          } else {
197	            dut.io.out(targetIndex).valid.expect(valids(o))
198	            dut.io.out(targetIndex).bits.expect(data(o))
199	          }
200	        }
201	      }
202	    }
203	  }
204	
205	  "ShiftVectorRight" in {
206	    simulate(new ShiftVectorRightTester) { dut =>
207	      val valids = Seq.fill(16)(Random.between(0, 2))
208	      val data = Seq.fill(16)(Random.between(0, 2147483647))
209	      for (i <- 0 until 16) {
210	        dut.io.in(i).valid.poke(valids(i))
211	        dut.io.in(i).bits.poke(data(i))
212	      }
213	
214	      for (t <- 0 until 16) {
215	        dut.io.shift.poke(t)
216	        for (o <- 0 until 16) {
217	          var targetIndex = o - t
218	          if (targetIndex < 0) {
219	            targetIndex = targetIndex + 16
220	          }
221	          if (targetIndex > o) {
222	            dut.io.out(targetIndex).valid.expect(0.U.asTypeOf(dut.io.out(0).valid))
223	            dut.io.out(targetIndex).bits.expect(0.U.asTypeOf(dut.io.out(0).bits))
224	          } else {
225	            dut.io.out(targetIndex).valid.expect(valids(o))
226	            dut.io.out(targetIndex).bits.expect(data(o))
227	          }
228	        }
229	      }
230	    }
