23	class AlignerTester[T <: Data](t: T, n: Int) extends Module {
24	    val io = IO(new Bundle {
25	        val in = Input(Vec(n, Valid(t)))
26	        val out = Output(Vec(n, Valid(t)))
27	    })
28	    val aligner = Module(new Aligner(t, n))
29	    for (i <- 0 until n) {
30	        aligner.io.in(i).valid := io.in(i).valid
31	        aligner.io.in(i).bits := io.in(i).bits.asUInt
32	
33	        io.out(i).valid := aligner.io.out(i).valid
34	        io.out(i).bits := aligner.io.out(i).bits.asTypeOf(t)
35	    }
36	}
