38	class AlignerSpec extends AnyFreeSpec with ChiselSim {
39	    "Basic" in {
40	        val n = 4
41	        simulate (new AlignerTester(UInt(32.W), n)) { dut =>
42	            for (i <- 0 until 1000) {
43	                var valid_in_count: BigInt = 0
44	                for (i <- 0 until n) {
45	                    val valid_in = Random.between(0, 2)
46	                    dut.io.in(i).valid.poke(valid_in)
47	                    valid_in_count += valid_in
48	
49	                    val data_in = Random.between(0, Math.pow(2, 32)).toInt
50	                    dut.io.in(i).bits.poke(data_in)
51	                }
52	
53	                var valid_out_count: BigInt = 0
54	                for (i <- 0 until n) {
55	                    valid_out_count += dut.io.out(i).valid.peek().litValue
56	                }
57	                assertResult(true) { valid_in_count == valid_out_count }
58	
59	                var outIdx = 0
60	                for (i <- 0 until n) {
61	                    val valid_in = dut.io.in(i).valid.peek().litValue
62	                    val data_in = dut.io.in(i).bits.peek().litValue
63	                    val data_out = dut.io.out(outIdx).bits.peek().litValue
64	                    if (valid_in == 1) {
65	                        assertResult(true) { data_in == data_out }
66	                        outIdx = outIdx + 1
67	                    }
68	                }
69	            }
70	        }
71	    }
72	
73	    "Bundle" in {
74	        val n = 4
75	        class bundleT extends Bundle {
76	            val a = UInt(32.W)
77	            val b = UInt(5.W)
78	            val c = UInt(12.W)
79	        }
80	        simulate (new AlignerTester(new bundleT, n)) { dut =>
81	            for (i <- 0 until 1000) {
82	                var valid_in_count: BigInt = 0
83	                for (i <- 0 until n) {
84	                    val valid_in = Random.between(0, 2)
85	                    dut.io.in(i).valid.poke(valid_in)
86	                    valid_in_count += valid_in
87	
88	                    dut.io.in(i).bits.a.poke(Random.between(0, Math.pow(2, dut.io.in(i).bits.a.getWidth)).toInt)
89	                    dut.io.in(i).bits.b.poke(Random.between(0, Math.pow(2, dut.io.in(i).bits.b.getWidth)).toInt)
90	                    dut.io.in(i).bits.c.poke(Random.between(0, Math.pow(2, dut.io.in(i).bits.c.getWidth)).toInt)
91	                }
92	
93	                var valid_out_count: BigInt = 0
94	                for (i <- 0 until n) {
95	                    valid_out_count += dut.io.out(i).valid.peek().litValue
96	                }
97	                assertResult(true) { valid_in_count == valid_out_count }
98	
99	                var outIdx = 0
100	                for (i <- 0 until n) {
101	                    val valid_in = dut.io.in(i).valid.peek().litValue
102	                    if (valid_in == 1) {
103	                        assertResult(dut.io.in(i).bits.a.peek().litValue) { dut.io.out(outIdx).bits.a.peek().litValue }
104	                        assertResult(dut.io.in(i).bits.b.peek().litValue) { dut.io.out(outIdx).bits.b.peek().litValue }
105	                        assertResult(dut.io.in(i).bits.c.peek().litValue) { dut.io.out(outIdx).bits.c.peek().litValue }
106	                        outIdx = outIdx + 1
107	                    }
108	                }
109	            }
110	        }
111	    }
112	}

