5	MEMORY {
6	    ITCM(rx): ORIGIN = 0x00000000, LENGTH = @@ITCM_LENGTH@@K
7	    DTCM(rw): ORIGIN = @@DTCM_ORIGIN@@, LENGTH = @@DTCM_LENGTH@@K
8	    EXTMEM(rw): ORIGIN = 0x20000000, LENGTH = 4096K
9	    DDR(rw): ORIGIN = 0x80000000, LENGTH = 2048M
10	}
11	
12	STACK_SIZE = DEFINED(__stack_size__) ? __stack_size__ : @@STACK_SIZE@@;
13	__stack_size = STACK_SIZE;
14	__stack_shift = 7;
15	__boot_hart = 0;
16	
17	ENTRY(_start)
18	
19	SECTIONS {
20	    /* ITCM data here */
21	    . = ORIGIN(ITCM);
22	    .text : ALIGN(16) {
23	        *(._init)
24	        *(.text)
25	        *(.text.*)
26	        . = ALIGN(16);
27	    } > ITCM
28	
29	    .init.array : ALIGN(16) {
30	      __init_array_start = .;
31	      __init_array_start__ = .;
32	      *(.init_array)
33	      *(.init_array.*)
34	      . = ALIGN(16);
35	      __init_array_end = .;
36	      __init_array_end__ = .;
37	    } > ITCM
38	
39	    .fini.array : {
40	      __fini_array_start = .;
41	      __fini_array_start__ = .;
42	      KEEP(*(.fini_array))
43	      KEEP(*(.fini_array.*))
44	      __fini_array_end = .;
45	      __fini_array_end__ = .;
46	    } > ITCM
47	
48	    .rodata : ALIGN(16) {
49	      *(.srodata)
50	      *(.srodata.*)
51	      *(.rodata)
52	      *(.rodata.*)
53	      *(.data.rel.ro)
54	      *(.data.rel.ro.*)
55	      . = ALIGN(16);
56	    } > ITCM
57	
58	    /* Static Thread Local Storage template */
59	    .tdata : {
60	        PROVIDE_HIDDEN (__tdata_start = .);
61	        *(.tdata .tdata.*)
62	        *(.gnu.linkonce.td.*)
63	        PROVIDE_HIDDEN (__tdata_end = .);
64	    } > DTCM
65	    PROVIDE (__tdata_size = SIZEOF (.tdata));
66	
67	    .tbss (NOLOAD) : {
68	        PROVIDE_HIDDEN (__tbss_start = .);
69	        PROVIDE_HIDDEN (__tbss_offset = ABSOLUTE (__tbss_start - __tdata_start));
70	        *(.tbss .tbss.*)
71	        *(.gnu.linkonce.tb.*)
72	        *(.tcommon)
73	        PROVIDE_HIDDEN (__tbss_end = .);
74	    } > DTCM
75	    PROVIDE (__tbss_size = SIZEOF (.tbss));
76	
77	    .htif : ALIGN(16) {
78	      KEEP(*(.htif))
79	    } > DTCM
80	
81	    .data : ALIGN(16) {
82	      __data_start__ = .;
83	      __data_start = .;
84	      /**
85	      * This will get loaded into `gp`, and the linker will use that register for
86	      * accessing data within [-2048,2047] of `__global_pointer$`.
87	      *
88	      * This is much cheaper (for small data) than materializing the
89	      * address and loading from that (which will take one extra instruction).
90	      */
91	      _global_pointer = . + 0x800;
92	      __global_pointer$ = . + 0x800;
93	      *(.sdata)
94	      *(.sdata.*)
95	      *(.data)
96	      *(.data.*)
97	      /**
98	       * Memory location for the return value from main,
99	       * which could be inspected by another core in the system.
100	       **/
101	      . = ALIGN(4);
102	      _ret = .;
103	      . += 4;
104	      . = ALIGN(16);
105	      __data_end__ = .;
106	      _edata = .;
107	    } > DTCM
108	
109	    .bss : ALIGN(16) {
110	      __bss_start__ = .;
111	      __bss_start = .;
112	      *(.sbss)
113	      *(.sbss.*)
114	      *(.bss)
115	      *(.bss.*)
116	      __bss_end__ = .;
117	      __bss_end = .;
118	    } > DTCM
119	
120	    .noinit (NOLOAD) : ALIGN(16) {
121	      KEEP(*(.noinit))
122	      KEEP(*(.noinit.*))
123	    } > DTCM
124	
125	    /* EXTMEM data here */
126	    . = ORIGIN(EXTMEM);
127	    .extdata : ALIGN(16) {
128	      __extdata_start__ = .;
129	      *(.extdata)
130	      *(.extdata.*)
131	      __extdata_end__ = .;
132	    } > EXTMEM
133	
134	    .extbss (NOLOAD) : ALIGN(16) {
135	      __extbss_start__ = .;
136	      *(.extbss)
137	      *(.extbss.*)
138	      __extbss_end__ = .;
139	    } > EXTMEM
140	
141	    /* DDR data here */
142	    .ddr_data : ALIGN(16) {
143	      __ddr_data_start__ = .;
144	      *(.ddr_data)
145	      *(.ddr_data.*)
146	      *(.cnidoom.wad)
147	      *(.cnidoom.weights)
148	      __ddr_data_end__ = .;
149	    } > DDR
150	
151	    .ddr_bss (NOLOAD) : ALIGN(16) {
152	      __ddr_bss_start__ = .;
153	      *(.ddr_bss)
154	      *(.ddr_bss.*)
155	      __ddr_bss_end__ = .;
156	    } > DDR
157	
158	    .heap : ALIGN(16) {
159	      __heap_start__ = .;
160	      __heap_start = .;
161	      @@HEAP_SIZE_SPEC@@
162	      __heap_end__ = .;
163	      __heap_end = .;
164	    } > @@HEAP_LOCATION@@
165	
166	    .stack : ALIGN(16) {
167	      @@STACK_START_SPEC@@
168	      __stack_start__ = .;
169	      __stack_start = .;
170	      . += STACK_SIZE;
171	      __stack_end__ = .;
172	    } > DTCM
173	
174	    _end = .;
175	}
