65	// TODO(lundong): Handle stdout and stderr separately
66	extern "C" int _write(int file, char* buf, int nbytes) {
67	  static int _write_line_buffer_len = 0;
68	  static char _write_line_buffer[LOG_MAX_SZ];
69	
70	  if (file != STDOUT_FILENO && file != STDERR_FILENO) {
71	    errno = EBADF;
72	    return -1;
73	  }
74	
75	  if (nbytes <= 0) {
76	    return 0;
77	  }
78	
79	  if (buf == NULL) {
80	    errno = EFAULT;
81	    return -1;
82	  }
83	
84	  int bytes_read = 0;
85	  char c;
86	  do {
87	    int len = _write_line_buffer_len;
88	    c = *(buf++);
89	    bytes_read++;
90	
91	    _write_line_buffer[len++] = c;
92	    if (len == LOG_MAX_SZ - 1 || c == '\n') {
93	      _write_line_buffer[len] = '\0';
94	    }
