66	__attribute__((weak)) int _open(const char* name, int flags, int mode) {
67	  uintptr_t name_addr = (uintptr_t)name;
68	  size_t name_len = strlen(name) + 1;
69	
70	  // Translate newlib flags to Linux host flags.
71	  // This is required because HTIF (mpact-riscv) passes flags directly to the
72	  // host's openat().
73	  int host_flags =
74	      flags & 3;  // O_RDONLY, O_WRONLY, O_RDWR are the same (0, 1, 2)
75	  if (flags & 0x0008) host_flags |= 0x400;  // newlib O_APPEND -> linux O_APPEND
76	  if (flags & 0x0200) host_flags |= 0x40;   // newlib O_CREAT  -> linux O_CREAT
77	  if (flags & 0x0400) host_flags |= 0x200;  // newlib O_TRUNC  -> linux O_TRUNC
78	  if (flags & 0x0800) host_flags |= 0x80;   // newlib O_EXCL   -> linux O_EXCL
79	  // Note: Other flags might need translation if used.
80	
81	  return htif_syscall_6args(SYS_openat, AT_FDCWD, name_addr, name_len,
82	                            host_flags, mode, 0);
83	}
