60	// Called to register a destructor for a global/static object.
61	int __cxa_atexit(void (*destructor)(void*), void* arg, void* dso_handle) {
62	  if (atexit_count >= MAX_ATEXIT_ENTRIES) {
63	    return -1;
64	  }
65	  atexit_entries[atexit_count].destructor = destructor;
66	  atexit_entries[atexit_count].arg = arg;
67	  atexit_count++;
68	  return 0;
69	}
70	
71	// Called to execute all registered destructors.
72	void __cxa_finalize(void* dso_handle) {
73	  for (int i = atexit_count - 1; i >= 0; i--) {
74	    if (atexit_entries[i].destructor) {
75	      atexit_entries[i].destructor(atexit_entries[i].arg);
76	    }
77	  }
78	  atexit_count = 0;
79	}
